<script setup>
import { ref, inject, computed, onMounted, onBeforeUnmount } from 'vue'
import { onBeforeRouteLeave } from 'vue-router'
import { adminRequest, formatDate } from '@/utils/adminApi'
const navigation=inject('adminOpenNavigation'),confirm=inject('adminConfirm')
const runs=ref([]),schedules=ref([]),error=ref(''),notice=ref(''),busy=ref(false),loading=ref(true),selected=ref(null),modal=ref(null)
const labels={all:'全量同步',favorites:'收藏同步',daily:'每日搜索',translations:'标签翻译'}
const states={queued:'排队中',in_progress:'执行中',success:'成功',failure:'失败',cancelled:'已取消',timed_out:'超时',completed:'已完成'}
const filter=ref('all'),visible=computed(()=>runs.value.filter(r=>filter.value==='all'||r.status===filter.value||r.conclusion===filter.value))
let timer,polling=false
async function load(){try{const [jobs,config]=await Promise.all([adminRequest('runs'),adminRequest('schedules')]);runs.value=jobs.runs;schedules.value=config.items.map(s=>{const draft=schedules.value.find(old=>old.kind===s.kind&&scheduleDirty(old));return draft||{...s,enabled:Boolean(s.enabled),original:JSON.stringify({enabled:Boolean(s.enabled),hour:s.hour,minute:s.minute,timezone:s.timezone})}});if(selected.value)selected.value=runs.value.find(r=>r.id===selected.value.id)||selected.value}catch(e){error.value=e.message}finally{loading.value=false}}
async function perform(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function dispatch(kind){if(!await confirm({title:`启动${labels[kind]}？`,description:'使用当前已保存的配置加入后台队列，成功后直接更新公开数据。',confirmLabel:'启动任务'}))return;await perform(async()=>{const result=await adminRequest('dispatch',{workflow:kind});notice.value=`任务 #${result.id} 已排队。`})}
async function all(){if(!await confirm({title:'分别同步全部数据？',description:'收藏、标签翻译和每日搜索将作为三个独立任务执行，各自成功后生效。',confirmLabel:'启动三个任务'}))return;await perform(async()=>{await adminRequest('dispatch-all');notice.value='三个同步任务已排队。'})}
async function cancel(run){if(!await confirm({title:'取消此任务？',description:'正在抓取的任务会终止，尚未发布的数据不会覆盖现有结果。',confirmLabel:'取消任务',danger:true}))return;await perform(async()=>{await adminRequest('job-cancel',{runId:run.id});notice.value='取消请求已提交。'})}
async function retry(run,original){if(!await confirm({title:original?'重试失败步骤？':'按当前配置重新执行？',description:original?'使用原任务的冻结配置，复用已成功步骤；原规则若已被修改，发布时仍会进行版本检查。':'全部步骤使用当前配置重新执行。',confirmLabel:original?'重试失败步骤':'重新执行'}))return;await perform(async()=>{await adminRequest('rerun',{runId:run.id,original});notice.value='任务已排队。'})}
function scheduleDirty(s){return s.original!==JSON.stringify({enabled:s.enabled,hour:s.hour,minute:s.minute,timezone:s.timezone})}
async function save(s){await perform(async()=>{await adminRequest('schedule-save',{kind:s.kind,version:s.version,enabled:s.enabled,hour:Number(s.hour),minute:Number(s.minute),timezone:s.timezone});s.original=JSON.stringify({enabled:s.enabled,hour:s.hour,minute:s.minute,timezone:s.timezone});notice.value='调度已保存，worker 会在十秒内读取新配置。'})}
onMounted(()=>{load();timer=setInterval(async()=>{if(polling||busy.value||document.visibilityState!=='visible')return;polling=true;try{const result=await adminRequest('runs');runs.value=result.runs;if(selected.value)selected.value=runs.value.find(r=>r.id===selected.value.id)||selected.value}catch(e){error.value=e.message}finally{polling=false}},3000)})
const dirty=computed(()=>schedules.value.some(scheduleDirty))
function beforeUnload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload)
onBeforeRouteLeave(async()=>!dirty.value||await confirm({title:'放弃未保存的调度修改？',description:'调度必须保存后才会执行。',confirmLabel:'放弃并离开',danger:true}))
onBeforeUnmount(()=>{clearInterval(timer);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template><div class="a-page" :aria-busy="busy||loading"><header class="a-page-heading"><div class="a-page-title"><button class="a-button a-mobile-menu" @click="navigation">菜单</button><div><h1>同步任务与调度</h1><p>任务在后台运行，配置在入队时冻结，结果成功后发布。</p></div></div><button class="a-button" :disabled="busy" @click="load">刷新</button></header><div v-if="error" class="a-alert a-alert-error" role="alert">{{error}}</div><div v-if="notice" class="a-alert a-alert-success" role="status">{{notice}}</div><div class="a-workflow-grid"><button v-for="kind in ['favorites','translations','daily']" :key="kind" class="a-card a-workflow" :disabled="busy" @click="dispatch(kind)"><strong>{{labels[kind]}}</strong><span>使用当前配置执行</span></button><button class="a-card a-workflow" :disabled="busy" @click="all"><strong>分别同步全部</strong><span>三个独立任务，分别发布结果</span></button></div>
<section class="a-card"><div class="a-section-heading"><div><h2>每日调度</h2><p>调度由常驻 worker 执行，关闭时不会自动抓取。</p></div></div><div class="v2-schedules"><article v-for="s in schedules" :key="s.kind"><h3>{{labels[s.kind]}}</h3><label><input v-model="s.enabled" type="checkbox" />启用每日执行</label><div class="v2-time"><label>时<input v-model.number="s.hour" type="number" min="0" max="23" :aria-label="labels[s.kind]+'执行小时'" /></label><label>分<input v-model.number="s.minute" type="number" min="0" max="59" :aria-label="labels[s.kind]+'执行分钟'" /></label><label>时区<select v-model="s.timezone"><option>Asia/Shanghai</option><option>UTC</option></select></label></div><p>下次执行：{{s.enabled?formatDate(s.next_run_at):'已暂停'}}</p><button class="a-button" :disabled="busy||!scheduleDirty(s)" @click="save(s)">保存调度</button></article></div></section>
<section class="a-card"><div class="a-section-heading"><h2>运行记录</h2><select v-model="filter"><option value="all">全部状态</option><option value="queued">排队中</option><option value="in_progress">运行中</option><option value="failure">失败</option><option value="success">成功</option></select></div><article v-for="run in visible" :key="run.id" class="v2-run"><div class="a-section-heading"><div><strong>#{{run.id}} {{run.name}}</strong><small>{{formatDate(run.createdAt)}}<span v-if="run.parentId"> · 来自任务 #{{run.parentId}}</span></small></div><span class="a-badge" :class="run.conclusion==='failure'?'a-badge-danger':run.conclusion==='success'?'a-badge-success':'a-badge-neutral'">{{run.cancelRequested&&run.status==='in_progress'?'正在取消':states[run.conclusion||run.status]}}</span></div><p>{{run.summary||'等待 worker 领取'}}</p><div v-for="step in run.steps" :key="step.name" class="v2-step"><strong>{{labels[step.name]}}</strong><span>{{states[step.status]}}</span><span v-if="step.progress.pages">{{step.progress.pages}} 页 · {{step.progress.items}} 条</span><span v-else-if="step.progress.batch">第 {{step.progress.batch}} 批</span><small>{{step.summary}}</small></div><div class="a-toolbar"><button class="a-button" @click="selected=run;modal.showModal()">配置与结果</button><button v-if="run.status!=='completed'" class="a-button" :disabled="busy||run.cancelRequested" @click="cancel(run)">取消任务</button><template v-else><button class="a-button" :disabled="busy" @click="retry(run,false)">按当前配置重跑</button><button v-if="run.conclusion!=='success'" class="a-button" :disabled="busy" @click="retry(run,true)">重试失败步骤</button></template></div></article><p v-if="!visible.length" class="a-empty">尚无任务记录。初次导入不代表已完成上游同步。</p></section>
<dialog ref="modal" class="a-modal"><div class="a-section-heading"><h2>任务 #{{selected?.id}}</h2><button class="a-button" @click="modal.close()">关闭</button></div><p>{{selected?.summary}}</p><p class="a-field-help">展示本次冻结的搜索规则与配置版本；密钥不返回浏览器。</p><article v-for="group in selected?.config.daily" :key="group.name" class="v2-run"><h3>{{group.name}}</h3><p>关键词：{{group.keyword||'无'}}</p><small>回溯 {{group.cutoffDays}} 天 · 页数 {{group.minPages||'不限'}}–{{group.maxPages||'不限'}} · 最低评分 {{group.minRating||'不限'}}</small></article></dialog></div></template>
